card.background:
[[[
  const s = entity.state;
  const p = variables.pal || {};
  const k = s === 'locked' ? 'locked'
          : (s === 'unlocked' || s === 'open') ? 'unlocked'
          : (s === 'locking' || s === 'unlocking' || s === 'opening') ? 'moving'
          : s === 'jammed' ? 'jammed' : 'unknown';
  return (p[k] || {}).bg || 'rgba(255,255,255,0.10)';
]]]

card.icon:
[[[
  const s = entity.state;
  /* the same five readings the colour below uses, so the glyph and the
     colour can never disagree about what the lock is doing */
  const k = s === 'locked' ? 'locked'
          : (s === 'unlocked' || s === 'open') ? 'unlocked'
          : (s === 'locking' || s === 'unlocking' || s === 'opening') ? 'moving'
          : s === 'jammed' ? 'jammed' : 'unknown';
  /* a room that named its own icon meant it */
  return variables.icon || (variables.icons || {})[k] || 'mdi:lock-question';
]]]

tap_action.confirmation:
[[[
  if (!variables.confirm) return false;
  const on = entity.state === 'locked';
  const who = variables.label || entity.attributes.friendly_name || 'this lock';
  return { text: `${on ? 'Unlock' : 'Lock'} ${who}?` };
]]]

